import React from 'react';
import { useQuery } from '@tanstack/react-query';
import orderService from '../../services/orderService';
import StatusBadge from '../../components/datadisplay/StatusBadge';

const MyOrders = () => {
    const { data, isLoading } = useQuery({
        queryKey: ['my-orders'],
        queryFn: () => orderService.getAllOrders()
    });

    return (
        <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">My Orders</h1>
            <p className="text-gray-500 mt-1 mb-6">View all your assigned orders</p>

            {isLoading ? (
                <div className="text-center py-8">
                    <div className="w-8 h-8 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin mx-auto" />
                </div>
            ) : (
                <div className="space-y-4">
                    {data?.data?.map(order => (
                        <div key={order.id} className="bg-white dark:bg-gray-800 rounded-xl p-4 shadow-sm border">
                            <div className="flex justify-between items-center">
                                <div>
                                    <p className="font-medium">{order.productName}</p>
                                    <p className="text-sm text-gray-500">Qty: {order.quantity}</p>
                                </div>
                                <div className="text-right">
                                    <p className="font-bold">${order.totalAmount.toFixed(2)}</p>
                                    <StatusBadge status={order.status} size="sm" />
                                </div>
                            </div>
                        </div>
                    ))}
                    {data?.data?.length === 0 && (
                        <p className="text-center text-gray-500 py-8">No orders found</p>
                    )}
                </div>
            )}
        </div>
    );
};

export default MyOrders;
